16	 * {@link org.springframework.samples.petclinic.util.Localities}), and HASH8 is the first 8
17	 * upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName}
18	 * (e.g. {@code 'NSW-1A2B3C4D'}). The code no longer carries a per-city sequence number, so it is a
19	 * pure function of the owner's region and identity and does not depend on other owners.
20	 *
21	 * <p>The computed code can nonetheless collide with an existing owner's {@code customerCode}. When it
22	 * does, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes the code
23	 * unique (e.g. {@code 'NSW-1A2B3C4D-2'}, then {@code '-3'}, …), and the de-duplicated code is stored.
24	 *
25	 * <p>Runs before {@link SaveOwner} so the new owner is not yet persisted and cannot collide with
26	 * itself.
27	 */
28	public class AssignCustomerCode {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String base = OwnerIdentities.customerCode(owner);
32	        Set<String> existing = new HashSet<>();
33	        for (Owner other : ownerRepository.findAll()) {
34	            if (owner.getId() != null && owner.getId().equals(other.getId())) {
35	                continue; // never collide with self
36	            }
37	            if (other.getCustomerCode() != null) {
38	                existing.add(other.getCustomerCode());
39	            }
40	        }
41	        String code = base;
42	        for (int n = 2; existing.contains(code); n++) {
43	            code = base + "-" + n;
44	        }
45	        owner.setCustomerCode(code);
46	    }
47	}
