3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
7	 * decimal digits contained in the owner's {@code customerCode}.
8	 *
9	 * <p>Non-digit characters (such as the '-' separators) are ignored; the remaining digits are
10	 * processed right-to-left, doubling every second digit starting with the rightmost and casting
11	 * out nines, and the check digit is {@code (10 - (sum % 10)) % 10}.
12	 */
13	public final class CheckDigits {
14	
15	    private CheckDigits() {
16	    }
17	
18	    public static int checkDigitFor(Owner owner) {
19	        return luhn(owner.getCustomerCode());
20	    }
21	
22	    /** Luhn check digit (0-9) over the decimal digits contained in {@code s}. */
23	    public static int luhn(String s) {
24	        int sum = 0;
25	        boolean dbl = true;
26	        for (int i = s.length() - 1; i >= 0; i--) {
27	            char c = s.charAt(i);
28	            if (c < '0' || c > '9') {
29	                continue;
30	            }
31	            int d = c - '0';
32	            if (dbl) {
33	                d *= 2;
34	                if (d > 9) {
35	                    d -= 9;
36	                }
37	            }
38	            sum += d;
39	            dbl = !dbl;
40	        }
41	        return (10 - (sum % 10)) % 10;
42	    }
43	}
