4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives fiscal-year values from an owner's business-day-adjusted {@code registrationDate}.
9	 *
10	 * <p>The fiscal year starts on 1 July and is labelled by the calendar year in which it ends, so a
11	 * date on or after 1 July belongs to the next calendar year's fiscal year (e.g. 2 July 2025 and
12	 * 30 June 2026 both fall in fiscal year 2026, {@code "FY26"}).
13	 */
14	public final class FiscalYears {
15	
16	    /** The month (1-based) on which the fiscal year begins: 1 July. */
17	    private static final int FISCAL_YEAR_START_MONTH = 7;
18	
19	    private FiscalYears() {
20	    }
21	
22	    /**
23	     * @param date any date.
24	     * @return the fiscal year (as a full calendar year) the date falls in: {@code year + 1} from
25	     *         1 July onward, otherwise {@code year}.
26	     */
27	    public static int fiscalYearOf(LocalDate date) {
28	        int year = date.getYear();
29	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year + 1 : year;
30	    }
31	
32	    /**
33	     * @param date any date.
34	     * @return the last two digits of the fiscal year, zero-padded (e.g. {@code "26"}).
35	     */
36	    public static String yearSegment(LocalDate date) {
37	        return String.format("%02d", fiscalYearOf(date) % 100);
38	    }
39	
40	    /**
41	     * @param owner the pet owner.
42	     * @return the fiscal year of the owner's {@code registrationDate}, formatted {@code "FY<YY>"},
43	     *         or {@code null} when the owner has no registrationDate.
44	     */
45	    public static String labelFor(Owner owner) {
46	        LocalDate registrationDate = owner.getRegistrationDate();
47	        if (registrationDate == null) {
48	            return null;
49	        }
50	        return "FY" + yearSegment(registrationDate);
51	    }
52	}
