5	/**
6	 * Derives an owner's {@code ownerSegment}, formatted {@code "<TIER>_<AREA>"}: one of
7	 * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
