27	     */
28	    public static String segmentFor(Owner owner) {
29	        String tier = MembershipLevels.cappedLevelFor(owner) >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
30	        String area = Localities.UNKNOWN.equals(Localities.localityFor(owner)) ? "REGIONAL" : "METRO";
