5	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}.
6	 *
7	 * <p>{@code seq} is a monotonically increasing sequence assigned by the emitter (see
8	 * {@code RespondWithOwnerCreated}). The {@code customerCode} field carries the owner's current
9	 * <em>primary identifier</em> (see {@link OwnerIdentities#primaryIdentifier(org.springframework.samples.petclinic.model.Owner)}):
10	 * the customer code today, and whatever replaces it later (e.g. the {@code memberId}) — the value
11	 * follows the primary identifier without any change here.
12	 *
13	 * <p>The record is immutable: once constructed the event cannot be altered before or after it is
14	 * published.
15	 */
16	public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel) {
17	
18	    /** The fixed {@code event} discriminator carried by every owner-created event. */
19	    public static final String EVENT = "OWNER_CREATED";
20	
21	    /** Render this event as a compact JSON object. */
22	    public String toJson() {
23	        return new StringBuilder()
24	                .append('{')
25	                .append("\"seq\":").append(this.seq)
26	                .append(",\"ownerId\":").append(this.ownerId)
27	                .append(",\"customerCode\":").append(quote(this.customerCode))
28	                .append(",\"membershipLevel\":").append(this.membershipLevel)
29	                .append(",\"event\":").append(quote(EVENT))
30	                .append('}')
31	                .toString();
32	    }
33	
34	    private static String quote(String value) {
35	        if (value == null) {
36	            return "null";
37	        }
38	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
39	        for (int i = 0; i < value.length(); i++) {
40	            char c = value.charAt(i);
41	            switch (c) {
42	                case '"':
43	                    sb.append("\\\"");
44	                    break;
45	                case '\\':
46	                    sb.append("\\\\");
47	                    break;
48	                case '\n':
49	                    sb.append("\\n");
50	                    break;
51	                case '\r':
52	                    sb.append("\\r");
53	                    break;
54	                case '\t':
55	                    sb.append("\\t");
56	                    break;
57	                default:
58	                    sb.append(c);
59	            }
60	        }
61	        return sb.append('"').toString();
62	    }
