10	/**
11	 * Rejects a create-owner request that exactly duplicates an existing owner's identity. The identity
12	 * is the {@code identityKey} — the SHA-256 of {@code telephone + email + soundex(lastName)} —
13	 * computed by {@link OwnerIdentities#identityKey(Owner)}, so an owner is a duplicate only when all
14	 * three components agree. Because the telephone is part of the key, two owners with the same last
15	 * name and postcode but a different telephone have different keys and are both allowed (they become a
16	 * soft match, see {@link CheckPossibleDuplicate}); only an exact key match is rejected with 409 (see
17	 * {@link DuplicateIdentityException}). This single key subsumes the former household-duplicate block.
18	 *
19	 * <p>A request may opt in with {@code sharesHousehold=true} to declare that it intentionally joins an
20	 * existing household; doing so <em>bypasses this block</em> entirely.
21	 *
22	 * <p>The email-domain blocklist is applied earlier by {@code ValidateOwnerFields} (a 400 before this
23	 * step runs), so any request reaching here already carries an allowed email.
24	 *
25	 * <p>Runs after {@link BuildOwner} so the new owner is built, and before {@link SaveOwner} so the new
26	 * owner is not compared against itself.
27	 */
28	public class CheckUniqueIdentity {
29	
30	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
31	            throws DuplicateIdentityException {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return; // declared household member: bypass the duplicate block.
34	        }
35	        String identityKey = OwnerIdentities.identityKey(owner);
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
38	                continue; // never collide with self (should not yet be persisted, but be safe)
39	            }
40	            if (Boolean.TRUE.equals(existing.getDeleted())) {
41	                continue; // a soft-deleted owner no longer blocks a new registration.
42	            }
43	            if (identityKey.equals(OwnerIdentities.identityKey(existing))) {
44	                throw new DuplicateIdentityException(owner.getHouseholdId());
45	            }
46	        }
47	    }
48	}
