1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone;
11	
12	/**
13	 * Derives an owner's {@code identityKey}: the single value all create-time duplicate detection is
14	 * expressed through. The key is the lower-case hex SHA-256 of
15	 * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, so two owners are
16	 * duplicates only when all three normalized components agree. Because the telephone is part of the
17	 * key, two owners sharing a last name (same soundex) and postcode but with <em>different</em>
18	 * telephones have different keys and are both allowed — they are a soft match, not a hard duplicate.
19	 *
20	 * <p>Each component is normalized the same way for every owner so the comparison is stable:
21	 * the telephone to E.164 (see {@link OwnerTelephone}), the email trimmed and lower-cased (blank or
22	 * absent represented as the empty string), and the last name reduced to its Soundex code. Every
23	 * normalization is idempotent, so the returned key equals the one used for comparison.
24	 */
25	public final class OwnerIdentities {
26	
27	    private OwnerIdentities() {
28	    }
29	
30	    public static String identityKey(Owner owner) {
31	        return sha256Hex(normalizeTelephone(owner.getTelephone()) + "|"
32	                + normalizeEmail(owner.getEmail()) + "|"
33	                + soundex(owner.getLastName()));
34	    }
35	
36	    /**
37	     * The American Soundex code of {@code name}: its first letter (upper-cased) followed by three
38	     * digits derived from the remaining consonants, zero-padded or truncated to length four. Letters
39	     * are coded b/f/p/v→1, c/g/j/k/q/s/x/z→2, d/t→3, l→4, m/n→5, r→6; vowels (a/e/i/o/u/y) reset the
40	     * run so an equal digit on either side is counted twice, while h/w are transparent and never
41	     * break a run. Non-letters are ignored; a name with no letters yields the empty string.
42	     */
43	    public static String soundex(String name) {
44	        if (name == null) {
45	            return "";
46	        }
47	        StringBuilder letters = new StringBuilder();
48	        for (int i = 0; i < name.length(); i++) {
49	            char c = name.charAt(i);
50	            if (Character.isLetter(c)) {
51	                letters.append(Character.toUpperCase(c));
52	            }
53	        }
54	        if (letters.length() == 0) {
55	            return "";
56	        }
57	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
58	        char prev = soundexDigit(letters.charAt(0));
59	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
60	            char c = letters.charAt(i);
61	            if (c == 'H' || c == 'W') {
62	                continue; // transparent: neither coded nor a break in the run
63	            }
64	            char d = soundexDigit(c);
65	            if (d != '0') {
66	                if (d != prev) {
67	                    code.append(d);
68	                }
69	                prev = d;
70	            }
71	            else {
72	                prev = '0'; // a vowel resets the run
73	            }
74	        }
75	        while (code.length() < 4) {
76	            code.append('0');
77	        }
78	        return code.toString();
79	    }
80	
81	    private static char soundexDigit(char c) {
82	        switch (c) {
83	            case 'B': case 'F': case 'P': case 'V':
84	                return '1';
85	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
86	                return '2';
87	            case 'D': case 'T':
88	                return '3';
89	            case 'L':
90	                return '4';
91	            case 'M': case 'N':
92	                return '5';
93	            case 'R':
94	                return '6';
95	            default:
96	                return '0';
97	        }
98	    }
99	
100	    /**
101	     * Builds the owner's {@code customerCode}: {@code '<REGION>-<HASH8>'}. REGION is the canonical
102	     * region derived from the owner's postcode (falling back to city — see {@link Localities}); HASH8
103	     * is the first 8 upper-case hex characters of SHA-256 over
104	     * {@code normalizedTelephone + lastName}. The telephone is normalized to E.164 the same way as in
105	     * {@link #identityKey(Owner)}, so owners differing only in telephone formatting share a code.
106	     */
107	    /**
108	     * The owner's <em>current primary identifier</em>: the single value that owner-scoped business
109	     * events publish to identify the owner. Today that is the {@link Owner#getCustomerCode()
110	     * customerCode}; when the customer code is later unified into the {@code memberId}, changing this
111	     * one method makes every event carry the {@code memberId} instead — the callers need not change.
112	     */
113	    public static String primaryIdentifier(Owner owner) {
114	        return owner.getCustomerCode();
115	    }
116	
117	    public static String customerCode(Owner owner) {
118	        String region = Localities.localityFor(owner.getCity(), owner.getPostcode());
119	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
120	        String hash8 = sha256Hex(normalizeTelephone(owner.getTelephone()) + lastName)
121	                .substring(0, 8).toUpperCase(Locale.ROOT);
122	        return region + "-" + hash8;
123	    }
124	
125	    /**
126	     * The owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
127	     * {@code normalizedLastName + "|" + postcode}. Owners with the same last name (normalized to a
128	     * trimmed, whitespace-collapsed, lower-cased form) and the same postcode therefore compute the
129	     * same identifier and belong to the same household automatically — no request has to declare it.
130	     */
131	    public static String householdId(Owner owner) {
132	        String lastName = normalizeName(owner.getLastName());
133	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode().trim();
134	        return sha256Hex(lastName + "|" + postcode).substring(0, 12);
135	    }
136	
137	    /** Full lower-case hex SHA-256 over the UTF-8 bytes of {@code value}. */
138	    private static String sha256Hex(String value) {
139	        try {
140	            byte[] digest = MessageDigest.getInstance("SHA-256")
141	                    .digest(value.getBytes(StandardCharsets.UTF_8));
142	            StringBuilder sb = new StringBuilder(digest.length * 2);
143	            for (byte b : digest) {
144	                sb.append(String.format("%02x", b));
145	            }
146	            return sb.toString();
147	        }
148	        catch (NoSuchAlgorithmException ex) {
149	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
150	        }
151	    }
152	
153	    private static String normalizeName(String value) {
154	        if (value == null) {
155	            return "";
156	        }
157	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
158	    }
159	
160	    private static String normalizeTelephone(String telephone) {
161	        try {
162	            return OwnerTelephone.toE164(telephone);
163	        }
164	        catch (InvalidTelephoneException ex) {
165	            // A value that cannot form a valid E.164 number cannot collide with one that can;
166	            // represent it by its raw form (or empty when absent) so comparison stays total.
167	            return telephone == null ? "" : telephone;
168	        }
169	    }
170	
171	    private static String normalizeEmail(String email) {
172	        if (email == null) {
173	            return "";
174	        }
175	        String trimmed = email.trim();
176	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
177	    }
178	}
