    if (memberId != null) {
        int i = 0;
        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
            i++;
        }
        if (i > 0) {
            return memberId.substring(0, i);
        }
    }
    return localityFor(owner.getCity(), owner.getPostcode());
}

